// Берём заявки за последние 24 часа и считаем статистику
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const now = DateTime.now().setZone('Europe/Moscow');
const rows = $input.all().map(i => i.json).filter(r => {
  const d = DateTime.fromFormat(String(r['Дата'] || ''), 'dd.MM.yyyy HH:mm', { zone: 'Europe/Moscow' });
  return d.isValid && now.diff(d, 'hours').hours <= 24;
});
const count = (key) => rows.reduce((acc, r) => { const v = r[key] || '—'; acc[v] = (acc[v] || 0) + 1; return acc; }, {});
const fmt = (obj) => Object.entries(obj).sort((a, b) => b[1] - a[1]).map(([k, v]) => `${k}: ${v}`).join(', ') || 'нет';
const open = rows.filter(r => r['Статус'] === 'новая');
const urgent = rows.filter(r => r['Срочность'] === 'высокая' || r['Категория'] === 'жалоба');
return [{ json: {
  total: rows.length,
  by_category: fmt(count('Категория')),
  by_source: fmt(count('Источник')),
  urgent_list: urgent.slice(0, 10).map(r => `• ${esc(r['Клиент'])}: ${esc(r['Суть'])} (${esc(r['Статус'])})`).join('\n') || 'нет',
  open_count: open.length,
  digest_input: rows.slice(0, 50).map(r => `${r['Категория']} | ${r['Срочность']} | ${r['Тон']} | ${r['Суть']}`).join('\n'),
  date: now.toFormat('dd.MM.yyyy'),
}}];

